"""Evaluation metrics quoted in the paper.

* Classification accuracy (%, higher is better)
* Expected Calibration Error, ECE (%, lower is better) - Eqn. of Naeini et al. (2015),
  implemented with the usual 15 equal-width confidence bins.
"""
from __future__ import annotations

from typing import Optional

import numpy as np
import torch
import torch.nn.functional as F


def accuracy(logits: torch.Tensor, targets: torch.Tensor) -> float:
    """Percentage of correct predictions."""
    if logits.numel() == 0:
        return float("nan")
    pred = logits.argmax(dim=-1)
    return 100.0 * (pred == targets).float().mean().item()


def expected_calibration_error(
    logits: torch.Tensor,
    targets: torch.Tensor,
    n_bins: int = 15,
    return_bins: bool = False,
):
    """Expected Calibration Error in percent.

    ``ECE = sum_b (n_b / N) * |acc(b) - conf(b)|`` computed on the top-1 confidence.
    """
    if logits.numel() == 0:
        return (float("nan"), None) if return_bins else float("nan")
    probs = F.softmax(logits.float(), dim=-1)
    conf, pred = probs.max(dim=-1)
    correct = (pred == targets).float()
    bin_edges = torch.linspace(0.0, 1.0, n_bins + 1, device=logits.device)
    ece = torch.zeros((), dtype=torch.float64, device=logits.device)
    n = logits.shape[0]
    stats = []
    for b in range(n_bins):
        lo, hi = bin_edges[b], bin_edges[b + 1]
        if b == n_bins - 1:
            mask = (conf >= lo) & (conf <= hi)
        else:
            mask = (conf >= lo) & (conf < hi)
        if mask.any():
            bin_acc = correct[mask].mean().double()
            bin_conf = conf[mask].mean().double()
            frac = mask.double().sum() / n
            ece += frac * (bin_acc - bin_conf).abs()
            stats.append((float(lo), int(mask.sum().item()), float(bin_acc), float(bin_conf)))
    value = float(ece.item() * 100.0)
    if return_bins:
        return value, stats
    return value


class OnlineMetrics:
    """Streaming accuracy / ECE (the paper reports accuracy and ECE over the stream)."""

    def __init__(self, n_bins: int = 15) -> None:
        self.n_bins = n_bins
        self.logits: list = []
        self.targets: list = []

    def update(self, logits: torch.Tensor, targets: torch.Tensor) -> None:
        if logits is None or logits.numel() == 0:
            return
        self.logits.append(logits.detach().float().cpu())
        self.targets.append(targets.detach().cpu())

    def _cat(self) -> tuple:
        if not self.logits:
            return torch.empty(0, 1), torch.empty(0, dtype=torch.long)
        return torch.cat(self.logits, 0), torch.cat(self.targets, 0)

    @property
    def num_samples(self) -> int:
        return int(sum(t.numel() for t in self.targets))

    def compute(self) -> dict:
        logits, targets = self._cat()
        return {
            "acc": accuracy(logits, targets),
            "ece": expected_calibration_error(logits, targets, self.n_bins),
            "num_samples": self.num_samples,
        }


class AverageMeter:
    def __init__(self) -> None:
        self.sum = 0.0
        self.count = 0

    def update(self, value: float, n: int = 1) -> None:
        self.sum += float(value) * n
        self.count += n

    @property
    def avg(self) -> float:
        return self.sum / self.count if self.count else float("nan")


def summarize(results: dict, key: str = "acc") -> dict:
    """Average a metric over the 15 ImageNet-C corruptions (or any dict of results)."""
    values = [v[key] for v in results.values() if v.get(key) is not None]
    return {
        "mean": float(np.mean(values)) if values else float("nan"),
        "std": float(np.std(values)) if values else float("nan"),
        "num": len(values),
    }

"""Adapter turning the FOA core algorithm into a ``TTAMethod``."""
from __future__ import annotations

from typing import Optional

import torch

from ..config import FOAConfig
from ..core.foa import FOA, FOAInterval
from ..core.statistics import FeatureStatistics
from .base import TTAMethod


class FOAMethod(TTAMethod):
    """FOA (batch-size > 1) or FOA-I (interval update for single samples)."""

    name = "FOA"

    def __init__(
        self,
        model,
        source_stats: FeatureStatistics,
        cfg: Optional[FOAConfig] = None,
        device: Optional[torch.device] = None,
    ) -> None:
        super().__init__(model, device=device)
        self.cfg = cfg or FOAConfig()
        self.last_extra = {}
        if self.cfg.interval and self.cfg.interval > 1:
            self.impl = FOAInterval(self.model, source_stats, cfg=self.cfg, device=self.device)
            self.name = f"FOA-I (I={self.cfg.interval}, {self.cfg.interval_store})"
        else:
            self.impl = FOA(self.model, source_stats, cfg=self.cfg, device=self.device)

    def reset(self) -> None:
        self.impl.reset()
        self.last_extra = {}

    @torch.no_grad()
    def step(self, images: torch.Tensor) -> Optional[torch.Tensor]:
        out = self.impl.step(images)
        if out is None:
            return None
        self.last_extra = dict(out.extra)
        return out.logits

    @torch.no_grad()
    def flush(self) -> Optional[torch.Tensor]:
        out = self.impl.flush()
        if out is None:
            return None
        self.last_extra = dict(out.extra)
        return out.logits

"""NoAdapt: the frozen source model, no adaptation at all."""
from __future__ import annotations

from typing import Optional

import torch

from .base import TTAMethod


class NoAdapt(TTAMethod):
    name = "NoAdapt"

    def __init__(self, model, device: Optional[torch.device] = None) -> None:
        super().__init__(model, device=device)
        self.last_extra = {}
        self.model.eval()

    @torch.no_grad()
    def step(self, images: torch.Tensor) -> torch.Tensor:
        return self.model(images.to(self.device))

"""T3A (Iwasawa & Matsuo, 2021) - test-time prototype-based classifier adjustment.

Official implementation: https://github.com/matsuolab/T3A
Appendix B.2 of the FOA paper: batch size 64 and ``M = 20`` supports to restore.

The classifier is replaced at test time by the cosine similarity between the query
feature and the supports of every class (the score of a class is the *largest* similarity
among its supports).  Supports are filtered down to ``filter_K`` and then to ``M`` entries
that are most similar to the class prototype.
"""
from __future__ import annotations

from typing import Optional

import torch
import torch.nn.functional as F

from .base import TTAMethod, features_and_logits


class T3A(TTAMethod):
    name = "T3A"

    def __init__(
        self,
        model,
        num_classes: int = 1000,
        filter_k: int = 100,
        num_supports: int = 20,
        device: Optional[torch.device] = None,
    ) -> None:
        super().__init__(model, device=device)
        self.model.eval()
        self.num_classes = num_classes
        self.filter_k = filter_k
        self.M = num_supports
        self.last_extra = {}
        self.reset()

    def reset(self) -> None:
        self.supports = None      # [num_classes, num_supports, d] kept as a list of tensors

    # ----------------------------------------------------------------------------------
    @torch.no_grad()
    def _score(self, features: torch.Tensor) -> torch.Tensor:
        assert self.supports is not None
        q = F.normalize(features, dim=1)
        logits = torch.full(
            (features.shape[0], self.num_classes), -1e4, device=features.device
        )
        for c, sup in enumerate(self.supports):
            if sup is None or sup.numel() == 0:
                continue
            s = F.normalize(sup, dim=1)
            logits[:, c] = (q @ s.t()).max(dim=1).values
        return logits

    @torch.no_grad()
    def _update_supports(self, features: torch.Tensor, logits: torch.Tensor) -> None:
        labels = logits.argmax(dim=1)
        if self.supports is None:
            self.supports = [None] * self.num_classes
        for i, label in enumerate(labels.tolist()):
            f = features[i : i + 1]
            if self.supports[label] is None:
                self.supports[label] = f
            else:
                self.supports[label] = torch.cat([self.supports[label], f], dim=0)
        for c in range(self.num_classes):
            sup = self.supports[c]
            if sup is None:
                continue
            for keep in (self.filter_k, self.M):
                if sup.shape[0] > keep:
                    proto = F.normalize(sup.mean(dim=0, keepdim=True), dim=1)
                    sims = (F.normalize(sup, dim=1) @ proto.t()).squeeze(1)
                    idx = sims.topk(keep, largest=True).indices
                    sup = sup[idx]
            self.supports[c] = sup

    # ----------------------------------------------------------------------------------
    @torch.no_grad()
    def step(self, images: torch.Tensor) -> torch.Tensor:
        feats, logits = features_and_logits(self.model, images.to(self.device))
        if self.supports is None:
            # first batch bootstraps the supports with the source classifier
            output = logits
        else:
            output = self._score(feats)
        self._update_supports(feats, output)
        return output

"""BN Adapt (Schneider et al., 2020 / Nado et al., 2020) - re-estimate the BatchNorm
statistics on the test batch.  Used as a baseline for the ResNet-50 experiment
(Table 10 of the FOA paper).
"""
from __future__ import annotations

from typing import Optional

import torch
import torch.nn as nn

from .base import TTAMethod, get_backbone


class BNAdapt(TTAMethod):
    name = "BN Adapt"

    def __init__(
        self,
        model,
        momentum: Optional[float] = None,
        device: Optional[torch.device] = None,
    ) -> None:
        super().__init__(model, device=device)
        self.momentum = momentum
        self.last_extra = {}
        self.model.eval()
        self.num_bn = 0
        for m in get_backbone(self.model).modules():
            if isinstance(m, (nn.BatchNorm1d, nn.BatchNorm2d, nn.BatchNorm3d)):
                m.train()  # use the statistics of the incoming test batch
                if momentum is not None:
                    m.momentum = momentum
                self.num_bn += 1

    @torch.no_grad()
    def step(self, images: torch.Tensor) -> torch.Tensor:
        return self.model(images.to(self.device))

